VS=""
FS=""
b=bytes.fromhex(VS)
print("=== vary3 VS 0x57 stores (SRC, 9-bit slot) ===")
i=0
while i<len(b)-7:
    if b[i]==0x57 and b[i+2] in (0x54,0x55) and b[i+5] in (0x40,0x41):
        src=b[i+3]; slot=b[i+4]|((b[i+5]&1)<<8); idx=slot>>5
        kind="POSITION" if idx<4 else f"user-varying#{(idx-4)//4}.comp{(idx-4)%4}"
        print(f"  @+{i:#05x}: SRC=r{src>>1:<3d} rawSLOT=0x{slot:03x} slotIdx={idx:2d}  {kind}")
        i+=8; continue
    i+=1
b=bytes.fromhex(FS)
print("=== vary3 FS iter ops (DST, coef) ===")
i=0
while i<len(b)-9:
    if b[i] in (0x2f,0xaf) and b[i+2]==0x54 and b[i+4]==0x03 and b[i+7]==0x02:
        dst=b[i+3]; coef=b[i+5]; mode=b[i+6]
        m={0x00:'linear',0x02:'centroid/sample',0x04:'persp-1/W'}.get(mode,hex(mode))
        print(f"  @+{i:#05x}: DST=r{dst>>1:<3d} COEF=0x{coef:02x} coefIdx={coef>>1:2d}  mode={m}")
        i+=10; continue
    i+=1
